// UpdateState defines model for UpdateState.
type UpdateState struct {
	// Available latestVersion is newer than the running version (never for a development build).
	Available bool       `json:"available"`
	CheckedAt *time.Time `json:"checkedAt,omitempty"`

	// CurrentVersion Version built into the running server: a release (`1.4.0`), a commit after one as
	// `git describe` writes it (`v1.4.0-12-gabc1234`), or the label of a development
	// build (a bare commit id, an image tag, `dev`).
	//
	//
	// Examples: 1.4.0, v1.4.0-12-gabc1234, dev
	CurrentVersion string `json:"currentVersion"`

	// Development currentVersion is no semantic version, so it cannot be compared with a release:
	// `available` stays false and the header carries no update badge. The
	// administration shows the build as a development state instead.
	Development bool `json:"development"`

	// Enabled The daily update check is on.
	Enabled bool `json:"enabled"`

	// Error Why the last check failed.
	Error *string `json:"error,omitempty"`

	// LatestVersion Newest published version from the release manifest.
	LatestVersion *string `json:"latestVersion,omitempty"`

	// Notes Release notes from the manifest (plain text).
	Notes *string `json:"notes,omitempty"`

	// Url Release page of latestVersion.
	Url *string `json:"url,omitempty"`
}

